import {
  DEMO_ACCOUNTS,
  DEMO_ADMIN_NOTIFICATIONS,
  DEMO_AUTH_CODE,
  DEMO_TOKEN_ADMIN,
  DEMO_TOKEN_USER,
  DEMO_USER_NOTIFICATIONS,
  DEMO_USER_PROFILE,
  PEDIATRIC_BAND_COUNTS,
  SEED_SUBMIT_NUM,
  VALIDATION_OK,
  buildReportPayload,
  createShowcaseSubmit,
} from './fixtures';
import { LOG_MAP } from '../assets/data/submit';

/** English progress log text for the public demo (default UI language). */
const demoLog = (key) => LOG_MAP[key][1];

function nowIso() {
  return new Date().toISOString();
}

function logEntry(message, status, offsetMs = 0) {
  return {
    message,
    status,
    timestamp: new Date(Date.now() + offsetMs).toISOString(),
  };
}

/** Build status_log + progress_status from submit age (ms). */
export function buildProgressForSubmit(submit) {
  const elapsed = Date.now() - new Date(submit.createdAt).getTime();

  if (elapsed < 4000) {
    return {
      progress_status: 1,
      log_data: {
        parameter_value: 'N/A',
        status_log: [
          logEntry(demoLog('VENV_DONE'), 'completed', -3000),
          logEntry(demoLog('SAMPLE_DONE'), 'completed', -1000),
          logEntry(demoLog('USER_RUN_START'), 'running', 0),
        ],
      },
    };
  }
  if (elapsed < 8000) {
    return {
      progress_status: 1,
      log_data: {
        parameter_value: 'N/A',
        status_log: [
          logEntry(demoLog('VENV_DONE'), 'completed', -7000),
          logEntry(demoLog('SAMPLE_DONE'), 'completed', -5000),
          logEntry(demoLog('USER_RUN_DONE'), 'completed', -2000),
          logEntry(demoLog('USER_EVAL_START'), 'running', 0),
        ],
      },
    };
  }

  submit.progress_status = 2;
  return {
    progress_status: 2,
    log_data: {
      parameter_value: 'N/A',
      status_log: [
        logEntry(demoLog('VENV_DONE'), 'completed', -12000),
        logEntry(demoLog('SAMPLE_DONE'), 'completed', -10000),
        logEntry(demoLog('USER_RUN_DONE'), 'completed', -6000),
        logEntry(demoLog('USER_EVAL_DONE'), 'completed', -1000),
      ],
    },
  };
}

const state = {
  counter: 1,
  submits: [createShowcaseSubmit()],
  unreadUserCount: DEMO_USER_NOTIFICATIONS.filter((n) => n.status === 'unread')
    .length,
  unreadAdminCount: DEMO_ADMIN_NOTIFICATIONS.filter((n) => n.status === 'unread')
    .length,
  userProfile: { ...DEMO_USER_PROFILE },
};

function ok(data, message = 'OK') {
  return { status: 200, message, data };
}

function listPage(content) {
  return ok({
    content,
    total_count: content.length,
    total_index: Math.max(1, Math.ceil(content.length / 10) || 1),
  });
}

function parsePath(url) {
  try {
    const u = new URL(url, 'https://demo.local');
    return u.pathname.replace(/\/+$/, '') || '/';
  } catch {
    return String(url || '').split('?')[0];
  }
}

function readFormValue(data, key) {
  if (!data) return null;
  if (typeof FormData !== 'undefined' && data instanceof FormData) {
    return data.get(key);
  }
  if (typeof data === 'object') return data[key];
  return null;
}

function parseJsonField(raw, fallback) {
  if (raw == null || raw === '') return fallback;
  if (typeof raw !== 'string') return raw;
  try {
    return JSON.parse(raw);
  } catch {
    return fallback;
  }
}

export function handleDemoRequest({ method = 'GET', url, data, headers }) {
  const path = parsePath(url);
  const m = String(method).toUpperCase();
  const auth = headers?.Authorization || headers?.authorization || '';

  if (m === 'POST' && path.endsWith('/login/user')) {
    const id = data?.login_id;
    const pw = data?.login_pw;
    if (id === DEMO_ACCOUNTS.user.login_id && pw === DEMO_ACCOUNTS.user.login_pw) {
      return { status: 200, data: ok({ token: DEMO_TOKEN_USER }) };
    }
    return {
      status: 401,
      data: {
        status: 401,
        error: {
          code: 'LOGIN_FAILED',
          message:
            'Invalid login ID or password. (Demo: Fakeuser1 / Demo1234!)',
        },
      },
    };
  }

  if (m === 'POST' && path.endsWith('/login/admin')) {
    const id = data?.login_id;
    const pw = data?.login_pw;
    if (
      id === DEMO_ACCOUNTS.admin.login_id &&
      pw === DEMO_ACCOUNTS.admin.login_pw
    ) {
      return { status: 200, data: ok({ token: DEMO_TOKEN_ADMIN }) };
    }
    return {
      status: 401,
      data: {
        status: 401,
        error: {
          code: 'LOGIN_FAILED',
          message: 'Admin login failed (check demo account).',
        },
      },
    };
  }

  void auth;

  if (m === 'POST' && path.endsWith('/id/find')) {
    return {
      status: 200,
      data: ok({
        login_id: DEMO_ACCOUNTS.user.login_id,
        create_time: '2024-01-15T00:00:00.000Z',
      }),
    };
  }

  if (m === 'POST' && path.endsWith('/check/auth')) {
    const payload = typeof data === 'string' ? parseJsonField(data, {}) : data;
    const code = String(readFormValue(payload, 'auth_number') || '').trim();
    if (code === DEMO_AUTH_CODE) {
      return { status: 200, data: ok({ verified: true }) };
    }
    return {
      status: 400,
      data: {
        status: 400,
        error: {
          code: 'AUTH_FAILED',
          message: `Invalid verification code. This demo does not send email — use ${DEMO_AUTH_CODE}.`,
        },
      },
    };
  }

  if (
    m === 'POST' &&
    (path.endsWith('/user/password/auth') || path.endsWith('/auth'))
  ) {
    return { status: 200, data: ok({ demo_code: DEMO_AUTH_CODE }) };
  }

  if (m === 'POST' && path.endsWith('/password/find')) {
    return { status: 200, data: ok({}) };
  }

  if (m === 'PATCH' && path.endsWith('/password/find')) {
    return { status: 200, data: ok({}) };
  }

  if (m === 'GET' && path.endsWith('/notification/user/read')) {
    state.unreadUserCount = 0;
    return { status: 200, data: ok({}) };
  }
  if (m === 'GET' && path.endsWith('/notification/admin/read')) {
    state.unreadAdminCount = 0;
    return { status: 200, data: ok({}) };
  }
  if (m === 'GET' && path.includes('/notification/count/admin')) {
    return {
      status: 200,
      data: ok({ new_notification_count: state.unreadAdminCount }),
    };
  }
  if (m === 'GET' && path.includes('/notification/count')) {
    return {
      status: 200,
      data: ok({ new_notification_count: state.unreadUserCount }),
    };
  }
  if (m === 'GET' && path.includes('/notification/admin/all')) {
    const history = DEMO_USER_NOTIFICATIONS.map((n) => ({
      from_info: {
        from: n.from_id === 'SYS' ? 'system' : 'admin',
        login_id: n.from_id === 'SYS' ? null : n.from_id,
      },
      to_info: { to: 'user', login_id: n.to_id },
      sent_time: n.sent_time,
      message: n.message,
    }));
    return { status: 200, data: listPage(history) };
  }
  if (m === 'GET' && path.endsWith('/notification/admin')) {
    return { status: 200, data: listPage(DEMO_ADMIN_NOTIFICATIONS) };
  }
  if (m === 'GET' && path.includes('/notification')) {
    return { status: 200, data: listPage(DEMO_USER_NOTIFICATIONS) };
  }

  if (m === 'GET' && path.includes('/answers/pediatric_band_counts')) {
    return {
      status: 200,
      data: ok({ counts: { ...PEDIATRIC_BAND_COUNTS } }),
    };
  }
  if (m === 'POST' && path.includes('/answers/get_sample_size')) {
    return { status: 200, data: ok({ total_sample_size: 120 }) };
  }

  if (m === 'POST' && path.endsWith('/submit/validation')) {
    return { status: 200, data: VALIDATION_OK };
  }

  if (m === 'POST' && (path.endsWith('/submit') || path === '/submit')) {
    state.counter += 1;
    const n = String(state.counter).padStart(3, '0');
    const submitNum = `SDEMO0${n}`;
    const title =
      readFormValue(data, 'submit_title') || `Demo Submission ${submitNum}`;
    const description =
      readFormValue(data, 'submit_description') || 'Interactive demo submission';
    const input_var_list = parseJsonField(readFormValue(data, 'input_var_list'), [
      'eeg_c3_m2',
      'eeg_c4_m1',
    ]);
    const output_var_list = parseJsonField(
      readFormValue(data, 'output_var_list'),
      ['sleep_stage_5']
    );
    const selected_subgroups = parseJsonField(
      readFormValue(data, 'selected_subgroups'),
      []
    );
    const pediatric_age_bands = parseJsonField(
      readFormValue(data, 'pediatric_age_bands'),
      null
    );
    const createdAt = nowIso();
    const submit = {
      submit_id: `demo-id-${submitNum}`,
      submit_num: submitNum,
      submit_title: String(title),
      submit_description: String(description),
      submit_time: createdAt,
      createdAt,
      progress_status: 1,
      job_id: `demo-job-${submitNum}`,
      files: [
        { name: 'main.py', size: 2048 },
        { name: 'requirements.txt', size: 128 },
        { name: 'submission.zip', size: 4096 },
      ],
      input_var_list,
      output_var_list,
      selected_subgroups,
      pediatric_age_bands,
      age_cohort: String(readFormValue(data, 'age_cohort') || 'adult'),
      sampling_mode: String(readFormValue(data, 'sampling_mode') || 'manual'),
      target_sample_size:
        Number(readFormValue(data, 'target_sample_size')) || 120,
      primary_parameter: String(
        readFormValue(data, 'primary_parameter') || 'accuracy'
      ),
      alpha: readFormValue(data, 'alpha') || 0.025,
      power: readFormValue(data, 'power') || 0.8,
      sigma: readFormValue(data, 'sigma') || 6.4,
      delta: readFormValue(data, 'delta') || 5,
      used_preset: String(readFormValue(data, 'used_preset') || '') === 'true',
      preset_key: String(readFormValue(data, 'preset_key') || ''),
    };
    state.submits.unshift(submit);
    return {
      status: 200,
      data: ok({ submit_id: submit.submit_id, submit_num: submit.submit_num }),
    };
  }

  const detailMatch = path.match(
    /\/submit\/submit_detail(?:\/admin)?\/([^/]+)$/
  );
  if (m === 'GET' && detailMatch) {
    const submitNum = decodeURIComponent(detailMatch[1]);
    const submit = state.submits.find((s) => s.submit_num === submitNum);
    if (!submit) {
      return { status: 404, data: { detail: 'Submit not found' } };
    }
    if (submit.progress_status === 2 && submit.submit_num === SEED_SUBMIT_NUM) {
      return {
        status: 200,
        data: {
          progress_status: 2,
          log_data: {
            parameter_value: 'N/A',
            status_log: [
              logEntry(demoLog('VENV_DONE'), 'completed', -30000),
              logEntry(demoLog('SAMPLE_DONE'), 'completed', -25000),
              logEntry(demoLog('USER_RUN_DONE'), 'completed', -15000),
              logEntry(demoLog('USER_EVAL_DONE'), 'completed', -5000),
            ],
          },
        },
      };
    }
    return { status: 200, data: buildProgressForSubmit(submit) };
  }

  if (m === 'GET' && path.includes('/submit/submit_table')) {
    return {
      status: 200,
      data: state.submits.map((s) => ({
        _id: s.submit_id,
        user_id: DEMO_ACCOUNTS.user.login_id,
        submit_num: s.submit_num,
        submit_time: s.submit_time,
        submit_title: s.submit_title,
        submit_description: s.submit_description,
        submit_path: '',
        files: s.files || [],
      })),
    };
  }

  if (
    m === 'GET' &&
    (path.endsWith('/submit/list') || path.includes('/submit/list/'))
  ) {
    const content = state.submits.map((s) => {
      if (s.progress_status !== 2) {
        const prog = buildProgressForSubmit(s);
        s.progress_status = prog.progress_status;
      }
      return {
        submit_num: s.submit_num,
        submit_title: s.submit_title,
        submit_description: s.submit_description,
        submit_time: s.submit_time,
        progress_status: s.progress_status,
        job_id: s.job_id,
        user_id: DEMO_ACCOUNTS.user.login_id,
      };
    });
    return { status: 200, data: listPage(content) };
  }

  if (m === 'POST' && /\/submit\/jobs\/(stop|restart)\//.test(path)) {
    return { status: 200, data: ok({ ok: true }) };
  }
  if (m === 'DELETE' && path.includes('/submit/jobs/delete/')) {
    return { status: 200, data: ok({ ok: true }) };
  }

  const reportMatch = path.match(/\/report(?:\/admin)?\/([^/]+)$/);
  if (m === 'GET' && reportMatch) {
    const submitNum = decodeURIComponent(reportMatch[1]);
    const submit = state.submits.find((s) => s.submit_num === submitNum);
    if (!submit) {
      return { status: 404, data: { detail: 'Report not found' } };
    }
    return { status: 200, data: buildReportPayload(submit) };
  }

  if (m === 'GET' && path.includes('/user/list')) {
    return { status: 200, data: listPage([]) };
  }

  if (m === 'GET' && path.endsWith('/user/profile')) {
    return {
      status: 200,
      data: ok({
        user: state.userProfile,
        submit: {
          total_count: state.submits.length,
          new_notification_count: state.unreadUserCount,
        },
      }),
    };
  }

  if (m === 'PATCH' && path.endsWith('/user/profile')) {
    const payload = typeof data === 'string' ? parseJsonField(data, {}) : data;
    const newTel = readFormValue(payload, 'new_tel');
    const newEmail = readFormValue(payload, 'new_email');
    if (newTel) state.userProfile.phone_number = String(newTel);
    if (newEmail) state.userProfile.email = String(newEmail);
    return { status: 200, data: ok({}) };
  }

  if (m === 'POST' && path.endsWith('/check/tel')) {
    return { status: 200, data: ok({ unique: true }) };
  }

  if (m === 'PATCH' && path.endsWith('/user/password')) {
    return { status: 200, data: ok({}) };
  }

  if (m === 'POST' && path.endsWith('/user/account/quit')) {
    return { status: 200, data: ok({}) };
  }

  return {
    status: 200,
    data: ok({}),
    unhandled: true,
  };
}
